create or replace function private.customer_account_access_enabled(p_company_id uuid) returns boolean language sql stable security definer set search_path to '' as $function$ select exists(select 1 from private.customer_accounts ca where ca.company_id=p_company_id and ca.account_status in ('trial','active')); $function$;
revoke all on function private.customer_account_access_enabled(uuid) from public,anon;
grant execute on function private.customer_account_access_enabled(uuid) to authenticated,service_role;
create or replace function private.current_company_ids() returns setof uuid language sql stable security definer set search_path to '' as $function$ select cm.company_id from public.company_memberships cm where cm.user_id=(select auth.uid()) and cm.active=true and private.customer_account_access_enabled(cm.company_id); $function$;
create or replace function private.current_location_ids() returns setof uuid language sql stable security definer set search_path to '' as $function$ select ula.location_id from public.user_location_access ula where ula.user_id=(select auth.uid()) and ula.active=true and private.customer_account_access_enabled(ula.company_id) union select cm.location_id from public.company_memberships cm where cm.user_id=(select auth.uid()) and cm.active=true and cm.location_id is not null and private.customer_account_access_enabled(cm.company_id); $function$;
create or replace function private.has_company_role(p_company_id uuid,allowed public.membership_role[]) returns boolean language sql stable security definer set search_path to '' as $function$ select private.customer_account_access_enabled(p_company_id) and exists(select 1 from public.company_memberships cm where cm.company_id=p_company_id and cm.user_id=(select auth.uid()) and cm.active=true and cm.role=any(allowed)); $function$;
create or replace function private.is_company_leader(p_company_id uuid) returns boolean language sql stable security definer set search_path to '' as $function$ select private.customer_account_access_enabled(p_company_id) and exists(select 1 from public.company_memberships m where m.company_id=p_company_id and m.user_id=(select auth.uid()) and m.active and m.role in ('owner','admin','executive')); $function$;
create or replace function private.can_access_location(p_company_id uuid,p_location_id uuid) returns boolean language sql stable security definer set search_path to '' as $function$ select private.customer_account_access_enabled(p_company_id) and (private.is_company_leader(p_company_id) or exists(select 1 from public.user_location_access ula where ula.company_id=p_company_id and ula.user_id=(select auth.uid()) and ula.location_id=p_location_id and ula.active) or exists(select 1 from public.company_memberships m where m.company_id=p_company_id and m.user_id=(select auth.uid()) and m.active and m.location_id=p_location_id)); $function$;
create or replace function public.operator_service_update_customer_account(p_actor_user_id uuid,p_company_id uuid,p_account_status text,p_plan_code text,p_trial_ends_at timestamptz,p_support_notes text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path to '' as $function$ declare v_before jsonb;v_after jsonb; begin if not exists(select 1 from private.platform_operators where user_id=p_actor_user_id and active=true and operator_role='platform_admin') then raise exception 'Platform administrator access required'; end if; if p_account_status not in ('trial','active','suspended','closed') then raise exception 'Invalid account status'; end if; if coalesce(p_plan_code,'') !~ '^[a-z0-9][a-z0-9_-]{1,39}$' then raise exception 'Plan code is invalid'; end if; select to_jsonb(ca) into v_before from private.customer_accounts ca where ca.company_id=p_company_id; if v_before is null then raise exception 'Customer account not found'; end if; update private.customer_accounts set account_status=p_account_status,plan_code=p_plan_code,trial_ends_at=p_trial_ends_at,support_notes=nullif(btrim(p_support_notes),''),customer_since=case when p_account_status='active' then coalesce(customer_since,current_date) else customer_since end,updated_at=now() where company_id=p_company_id; select jsonb_build_object('company_id',ca.company_id,'account_status',ca.account_status,'plan_code',ca.plan_code,'trial_ends_at',ca.trial_ends_at,'support_notes',ca.support_notes,'customer_since',ca.customer_since,'core_version',ca.core_version,'target_core_version',ca.target_core_version,'previous_core_version',ca.previous_core_version,'release_status',ca.release_status) into v_after from private.customer_accounts ca where ca.company_id=p_company_id; insert into private.operator_audit_events(request_id,actor_user_id,company_id,action,target_type,target_id,before_json,after_json) values(p_request_id,p_actor_user_id,p_company_id,'customer.account_updated','customer_account',p_company_id,v_before,v_after) on conflict(request_id) do nothing; return v_after; end $function$;
revoke all on function public.operator_service_update_customer_account(uuid,uuid,text,text,timestamptz,text,uuid) from public,anon,authenticated;
grant execute on function public.operator_service_update_customer_account(uuid,uuid,text,text,timestamptz,text,uuid) to service_role;